	/* @Override */
	public bool isDescendant(Namespace @namespace) {
		if (this == @namespace.getSymbol()) {
			return true;
		}
		Namespace parent = @namespace.getParentNamespace();
		while (parent != null) {
			Symbol s = parent.getSymbol();
			if (this.equals(s)) {
				return true;
			}
			parent = parent.getParentNamespace();
		}

		return false;
	}

	/* @Override */
	public bool isValidParent(Namespace parent) {
		return symbolMgr.isMyNamespace(parent);
